SELECT 'Cascade Locks Marine Park','park','park','A Columbia River waterfront park in Cascade Locks with river views, lawns, marina access and a pedestrian connection to Thunder Island.','An easy Columbia River Gorge stop with excellent views toward the Bridge of the Gods and access to Thunder Island.','Gorge road-trippers, families, photographers, picnickers and visitors exploring the Bridge of the Gods and Cascade Locks.','Walk across the footbridge to Thunder Island for broad Columbia River views and one of the best nearby perspectives on the Bridge of the Gods.',45.6698,-121.8904,'355 Wa Na Pa St, Cascade Locks, OR 97014','US','United States','Oregon','Cascade Locks','Columbia River Gorge','97014','us-or-cascade-locks','America/Los_Angeles','Open 24 hours','approved','Oleksandr Dmytruk',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0,1,'roviq','trusted'
WHERE NOT EXISTS (SELECT 1 FROM places WHERE lower(name)='cascade locks marine park');

